    use serial_test::serial;
    use std::fs::{create_dir_all, remove_dir_all, write};
    use std::path::PathBuf;
    use std::process::Command;
    use std::time::{Instant, SystemTime, UNIX_EPOCH};
    use std::{env, mem};

    // `list_client_names` / `list_all_models` cache the first AppConfig they
    // see in process-wide OnceLocks. Several tests reach them through configs
    // with an empty client list, which would permanently pin every later
    // model lookup in this process to "unknown model" and make any test that
    // needs a resolvable model dependent on test ordering. Seed the caches
    // before any test runs with a client, "test-seeded", exposing a single
    // embedding model. Deliberately NO chat model: some tests assert that no
    // chat model is available, and chat lookups don't need one — a
    // "test-seeded:<anything>" chat id resolves through the create-from-name
    // fallback because the client name is registered.
    //
    // `unsafe` is ctor's required acknowledgment that this runs before main;
    // the body only allocates and initializes OnceLocks, both of which are
    // sound pre-main.
    #[ctor::ctor(unsafe)]
    fn seed_model_registries() {
        use crate::client::{ClientConfig, ModelData, list_all_models, list_client_names};

        let mut client = ClientConfig::default();
        if let ClientConfig::OpenAIConfig(config) = &mut client {
            config.name = Some("test-seeded".to_string());
            let mut embedder = ModelData::new("test-embedder");
            embedder.model_type = "embedding".to_string();
            config.models = vec![embedder];
        }
        // A claude client is seeded alongside it so tests can exercise
        // provider-quirk inheritance through the create-from-name fallback.
        // It deliberately carries one embedding model: an empty `models` list
        // would fall back to the full embedded claude catalog and register
        // real chat models, breaking the no-chat-model invariant above.
        // The test-dual-model pair shares one id across two types, mirroring
        // jina:jina-colbert-v2, for the type-aware lookup tests.
        let claude: ClientConfig = serde_yaml::from_str(
            "type: claude\nmodels:\n  - name: test-claude-embedder\n    type: embedding\n  - name: test-dual-model\n    type: embedding\n  - name: test-dual-model\n    type: reranker\n",
        )
        .unwrap();
        let config = AppConfig {
            clients: vec![client, claude],
            ..AppConfig::default()
        };
        let _ = list_client_names(&config);
        let _ = list_all_models(&config);
    }

    /// Pins both the config dir and the workspace config dir to absolute
    /// temp paths so no `.coyote/` under the real CWD leaks into the test,
    /// and clears the sessions-dir overrides (`COYOTE_SESSIONS_DIR`, plus
    /// `HELPER_DATA_DIR` for the `helper` fixture agent) so Global-scope
    /// writes cannot escape into the developer's real sessions dir.
    struct TestConfigDirGuard {
        keys: [(String, Option<std::ffi::OsString>); 4],
        path: PathBuf,
        workspace_root: PathBuf,
    }

    impl TestConfigDirGuard {
        fn new() -> Self {
            let unique = SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .unwrap()
                .as_nanos();
            let path = env::temp_dir().join(format!("coyote-request-context-tests-{unique}"));
            create_dir_all(&path).unwrap();
            let workspace_root =
                env::temp_dir().join(format!("coyote-request-context-ws-{unique}"));
            let workspace_path = workspace_root.join(WORKSPACE_COYOTE_DIR_NAME);
            create_dir_all(&workspace_path).unwrap();
            let keys = [
                (get_env_name("config_dir"), Some(path.as_os_str())),
                (
                    get_env_name("workspace_config_dir"),
                    Some(workspace_path.as_os_str()),
                ),
                (get_env_name("sessions_dir"), None),
                (
                    format!("{}_DATA_DIR", utils::normalize_env_name("helper")),
                    None,
                ),
            ]
            .map(|(key, value)| {
                let previous = env::var_os(&key);
                unsafe {
                    match value {
                        Some(value) => env::set_var(&key, value),
                        None => env::remove_var(&key),
                    }
                }
                (key, previous)
            });
            Self {
                keys,
                path,
                workspace_root,
            }
        }
    }

    impl Drop for TestConfigDirGuard {
        fn drop(&mut self) {
            for (key, previous) in &self.keys {
                if let Some(previous) = previous {
                    unsafe {
                        env::set_var(key, previous);
                    }
                } else {
                    unsafe {
                        env::remove_var(key);
                    }
                }
            }
            let _ = remove_dir_all(&self.path);
            let _ = remove_dir_all(&self.workspace_root);
        }
    }

    fn default_app_state() -> Arc<AppState> {
        Arc::new(AppState::test_default())
    }

    fn create_test_ctx() -> RequestContext {
        RequestContext::new(default_app_state(), WorkingMode::Cmd)
    }

    fn priced_model() -> Model {
        let mut data = ModelData::new("test");
        data.input_price = Some(10.0);
        data.output_price = Some(100.0);
        data.cache_read_price = Some(1.0);
        data.cache_write_price = Some(20.0);
        Model::from_config("provider", &[data]).remove(0)
    }

    /// Both review graphs import the lint from `<agents dir>/.shared`, so
    /// the installed tree, not the source tree, is what production runs.
    /// A dot-directory the embed or the installer skipped would leave every
    /// gauntlet BLOCKED with `GAUNTLET_REVIEW_INCOMPLETE: debris`.
    #[test]
    #[serial]
    fn install_builtin_agents_ships_the_shared_debris_lint_the_review_graphs_import() {
        if !cmd_available("python3") || !cmd_available("git") {
            eprintln!("skipping: python3 or git not available");
            return;
        }
        let _guard = TestConfigDirGuard::new();
        Agent::install_builtin_agents(InstallMode::Skip).unwrap();

        let agents = paths::agents_data_dir();
        let shared = agents.join(".shared").join("debris.py");
        let source = Path::new(env!("CARGO_MANIFEST_DIR")).join("assets/agents/.shared/debris.py");
        assert_eq!(
            read_to_string(&shared).expect(".shared/debris.py must be installed"),
            read_to_string(&source).unwrap(),
            "the installed shared module must be the embedded source"
        );

        let repo = debris_repo();
        for wrapper in [
            "review-gauntlet/scripts/debris_lint.py",
            "adversary/scripts/debris_lint.py",
        ] {
            let state = serde_json::json!({
                "project_dir": repo.to_string_lossy(),
                "diff_spec": "staged",
                "diff_spec_resolved": "staged",
            });
            let out = Command::new("python3")
                .arg(agents.join(wrapper))
                .env("GRAPH_STATE", state.to_string())
                .env_remove("GRAPH_STATE_FILE")
                .output()
                .unwrap();
            assert!(
                out.status.success(),
                "{wrapper}: {}",
                String::from_utf8_lossy(&out.stderr)
            );
            let result: serde_json::Value = serde_json::from_slice(&out.stdout).unwrap();
            let summary = result["debris_summary"].as_str().unwrap_or_default();
            assert!(
                summary.contains("1 hit(s)"),
                "the installed {wrapper} must find the planted em dash through the installed \
                 .shared module, got {result}"
            );
            assert!(
                result["debris_error"]
                    .as_str()
                    .unwrap_or_default()
                    .is_empty()
                    && result["pipeline_faults"]
                        .as_array()
                        .map(|f| f.is_empty())
                        .unwrap_or(true),
                "the installed {wrapper} must not report an import fault: {result}"
            );
        }
        let _ = remove_dir_all(&repo);
        for dir in [
            agents.join(".shared"),
            agents.join("review-gauntlet/scripts"),
            agents.join("adversary/scripts"),
        ] {
            let _ = remove_dir_all(dir.join("__pycache__"));
        }
    }

    #[test]
    fn generate_prompt_context_emits_token_usage_vars() {
        let mut ctx = create_test_ctx();
        ctx.session = Some(Session::default());
        ctx.record_token_usage(
            Some(TokenUsage {
                input_tokens: Some(120),
                output_tokens: Some(8),
                cache_creation_input_tokens: None,
                cache_read_input_tokens: Some(100),
            }),
            &priced_model(),
        );
        ctx.record_token_usage(
            Some(TokenUsage {
                input_tokens: Some(30),
                output_tokens: Some(2),
                cache_creation_input_tokens: Some(40),
                cache_read_input_tokens: None,
            }),
            &priced_model(),
        );

        let app = ctx.app.config.clone();
        let vars = ctx.generate_prompt_context(&app);

        assert_eq!(
            vars.get("last_input_tokens").map(String::as_str),
            Some("30")
        );
        assert_eq!(
            vars.get("last_output_tokens").map(String::as_str),
            Some("2")
        );
        assert_eq!(
            vars.get("last_cache_creation_tokens").map(String::as_str),
            Some("40")
        );
        assert!(!vars.contains_key("last_cache_read_tokens"));
        assert_eq!(
            vars.get("total_input_tokens").map(String::as_str),
            Some("150")
        );
        assert_eq!(
            vars.get("total_output_tokens").map(String::as_str),
            Some("10")
        );
        assert_eq!(
            vars.get("total_cache_read_tokens").map(String::as_str),
            Some("100")
        );
        assert_eq!(
            vars.get("total_cache_creation_tokens").map(String::as_str),
            Some("40")
        );
        // 30×10 + 2×100 + 40×20 per 1M = 0.0013; first call adds 0.0021.
        assert_eq!(vars.get("last_cost").map(String::as_str), Some("0.0013"));
        assert_eq!(vars.get("total_cost").map(String::as_str), Some("0.0034"));
    }

