        let mut ctx = RequestContext::new(default_app_state(), WorkingMode::Cmd);

        run_async(ctx.update("compression_keep_last 6", utils::create_abort_signal())).unwrap();
        assert_eq!(ctx.app.config.compression_keep_last, 6);
