        let out = run_gauntlet_script("default_lanes.py", &json!({}));
        assert_eq!(out["forced_lanes"], json!(["code-review", "adversary"]));
        assert!(
            out["lanes_degraded"]
                .as_str()
                .unwrap()
                .contains("deterministic defaults"),
            "the degradation note must name the deterministic defaults: {out}"
        );

